const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const root=$('#connect-root'),dialog=$('#connect-dialog'),url=new URL(location.href),adminPage=location.pathname==='/admin/connect',insightsPage=['/manager/connect','/top-management/connect'].includes(location.pathname);
const state={init:null,admin:null,feed:[],next:null,review:null,adminTab:url.searchParams.get('tab')||'spotlight',view:url.searchParams.get('view')||'community',tickets:new Map()};
const icons={'Appreciate':'♡','Well Done':'👏','Celebrate':'🎉','Inspiring':'💡','Great Teamwork':'🤝','Amazing':'✦'},moods=[['Great','😄'],['Good','🙂'],['Okay','😐'],['Low','😔'],['Stressed','😫']],statusLabels=['Received','Under Review','Being Explored','Planned','Implemented','Closed with Explanation'],criteria=['Peer evidence','Statement quality','CATALYST alignment','Contribution / impact','Nominator diversity'];
const month=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit'}).format(new Date()),day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const fmt=v=>v?new Date(v.length===7?v+'-01T12:00:00Z':v).toLocaleDateString('en-MY',{timeZone:'Asia/Kuala_Lumpur',...(v.length===7?{month:'long',year:'numeric'}:{day:'numeric',month:'short'})}):'',nameOf=id=>state.init.colleagues.find(e=>e.id===id)?.name||'Colleague';
function avatar(id,name,large=false){return `<span class="avatar${large?' large':''}" aria-hidden="true">${esc((name||'IUC').split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join(''))}${id?`<img src="/api/people-hub/photos/${encodeURIComponent(id)}" alt="" loading="lazy">`:''}</span>`}
document.addEventListener('error',e=>{if(e.target.matches?.('.avatar img'))e.target.remove()},true);
async function api(path,method='GET',data){const r=await fetch('/api/connect/'+path,{method,headers:data===undefined?{}:{'content-type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});const b=await r.json();if(!r.ok)throw Error(b.error||'This action could not be completed.');return b}
function toast(message){const t=$('#connect-toast');t.textContent=message;t.hidden=false;clearTimeout(state.toast);state.toast=setTimeout(()=>t.hidden=true,5000)}
function empty(title,text,action=''){return `<div class="empty"><span class="empty-symbol" aria-hidden="true">✧</span><h2>${esc(title)}</h2><p>${esc(text)}</p>${action}</div>`}
function options(list,selected=''){return list.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function colleagues(selected='',eligible=null){return '<option value="">Choose a colleague…</option>'+state.init.colleagues.filter(e=>!eligible||eligible.includes(e.id)).map(e=>`<option value="${esc(e.id)}" ${e.id===selected?'selected':''}>${esc(e.name)} · ${esc(e.department)}</option>`).join('')}
function field(label,name,type='text',extra='',value=''){return `<label class="field">${esc(label)}<input name="${name}" type="${type}" ${extra} value="${esc(value)}"></label>`}
function textarea(label,name,max=1500,required=true,value=''){return `<label class="field">${esc(label)}<textarea name="${name}" maxlength="${max}" rows="4" ${required?'required':''}>${esc(value)}</textarea></label>`}
function select(label,name,opts,extra=''){return `<label class="field">${esc(label)}<select name="${name}" ${extra}>${opts}</select></label>`}
function formTail(label){return `<p class="form-error error" role="alert"></p><div class="form-actions"><button type="button" data-action="close-dialog">Cancel</button><button class="primary" type="submit">${esc(label)}</button></div>`}
function modal(title,html,kicker='NADI CONNECT'){dialog.innerHTML=`<div class="dialog-head"><div><div class="connect-kicker">${esc(kicker)}</div><h2 id="dialog-title">${esc(title)}</h2></div><button type="button" data-action="close-dialog" aria-label="Close">×</button></div>${html}`;if(!dialog.open)dialog.showModal();}
function greet(){const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kuala_Lumpur',hour:'numeric',hourCycle:'h23'}).format(new Date())),name=state.init.employee?.name?.split(' ')[0];return `${hour<12?'Good morning':hour<18?'Good afternoon':'Good evening'}${name?', '+name:''} 👋`}
function shell(content){const i=state.init;if(root.dataset.home){const greeting=document.getElementById('home-greeting');if(greeting)greeting.textContent=greet();const pulse=document.getElementById('today-pulse');if(pulse&&i.employee)pulse.innerHTML=moodBox();document.dispatchEvent(new CustomEvent('nadi:people',{detail:i.colleagues}));if(state.homeDialog){const title=state.homeDialog;state.homeDialog=null;modal(title,content);return;}root.innerHTML='<div class="connect-wrap"><div id="connect-content">'+content+'</div></div>';root.querySelectorAll('a[href^="/connect"]').forEach(a=>a.href=a.getAttribute('href').replace('/connect','/')+'#community');placeHomeStories();return;}root.innerHTML=`<div class="connect-wrap"><div class="connect-top"><div class="connect-wordmark"><img src="/iuc-logo.png" alt="IUC"><span>NADI CONNECT<small>RECOGNITION · ENGAGEMENT · VOICE · BELONGING</small></span></div><div class="connect-top-actions">${i.employee?'<button data-action="notifications">♧ Inbox</button><button data-action="preferences">Preferences</button>':''}${i.admin&&!adminPage?'<a class="small" href="/admin/connect">P&C workspace ↗</a>':''}</div></div><header class="connect-hero"><div><span class="connect-kicker">${adminPage?'PEOPLE & CULTURE':insightsPage?'CULTURE & INCLUSION':'A LITTLE CONNECTION GOES A LONG WAY'}</span><h1>${adminPage?'Help a culture of <em>appreciation grow.</em>':insightsPage?'Make room for <em>everyone.</em>':`${esc(greet())}<br>We’re better <em>together.</em>`}</h1><p>${adminPage?'Listen, recognise meaningful contribution and show employees what their voice changes.':insightsPage?'Use safe team trends to support belonging, recognition and a thoughtful response.':'Share a moment. Appreciate a colleague. Have your say.<br> This is your place to feel connected at IUC.'}</p></div>${i.employee?'<button class="hero-appreciate" data-action="appreciate">✦ Make Someone’s Day</button>':'<a class="primary-link" href="/connect">Open the community</a>'}</header><nav class="connect-nav" aria-label="Nadi Connect sections"><a href="/#community">Back to Nadi</a>${i.admin?`<a href="/admin/connect" class="${adminPage?'selected':''}">P&C workspace</a>`:''}${!i.admin&&i.manager?`<a href="/manager/connect" class="${insightsPage?'selected':''}">Team insights</a>`:''}${!i.admin&&i.leadership?`<a href="/top-management/connect" class="${insightsPage?'selected':''}">Culture insights</a>`:''}</nav><div id="connect-content">${content}</div><p class="live-note">Recognition celebrates contribution. It does not change MPC ratings, CPD credit or employment decisions.</p></div>${i.employee?'<nav class="mobile-actions" aria-label="Connect quick actions"><button data-action="compose"><span>＋</span>Post</button><button data-action="appreciate"><span>✦</span>Appreciate</button><button data-action="mood"><span>☀</span>Check In</button><button data-action="voice-form"><span>◇</span>Your Voice</button></nav>':''}`;}
// Move the same live cards, keeping one copy and all delegated actions intact.
function placeHomeStories(){
 const aside=root.querySelector('.community-aside');if(!aside)return;
 for(const [source,target] of [['.spotlight-card','#home-spotlight'],['.voice-action-card','#home-voice']]){const card=aside.querySelector(source),slot=document.querySelector(target);if(card&&slot)slot.replaceChildren(card);}
 const extras=document.querySelector('#home-community-extras');if(extras){extras.replaceChildren(...aside.children);extras.hidden=!extras.children.length;}
 if(!aside.children.length)aside.remove();
}
function postCard(p){const subject=p.subjectId?nameOf(p.subjectId):'',meta=p.metadata||{},special=p.kind==='recognition'||p.kind==='spotlight';return `<article class="card post-card ${esc(p.kind)}" data-post="${esc(p.id)}"><div class="post-head">${avatar(p.authorId,p.author)}<div class="post-by"><strong>${esc(p.author)}</strong><span>${esc(p.department)}${p.department?' · ':''}${esc(fmt(p.createdAt))} · ${esc(p.visibility)}</span></div><span class="post-kind">${p.kind==='recognition'?'APPRECIATION':p.kind==='spotlight'?'MONTHLY SPOTLIGHT':p.kind==='campaign'?'CAMPAIGN':p.kind==='story'?'PEOPLE OF IUC':p.kind==='feeling'?'SHARED FEELING':'COMMUNITY'}</span></div>${special?`<div class="recognition-heading"><span class="symbol" aria-hidden="true">${p.kind==='spotlight'?'🏆':'✦'}</span><div><strong>${esc(meta.name||subject)}</strong><small>${esc(meta.category)}${meta.period?' · '+esc(fmt(meta.period)):''}</small></div></div>`:meta.title?`<h2>${esc(meta.title)}</h2>`:''}${p.kind==='feeling'?`<div class="feeling-heading"><span aria-hidden="true">${moods.find(([m])=>m===meta.mood)?.[1]||'🙂'}</span><div><strong>Feeling ${esc(meta.mood)}</strong><small>${esc(fmt(meta.day))} · Shared with all IUC colleagues</small></div></div>`:''}${p.body?`<p class="post-body">${esc(p.body)}</p>`:''}${meta.value?`<span class="value-chip">${esc(meta.value)}</span>`:''}${p.mentions?.length?`<div class="mentions">With ${p.mentions.map(m=>esc(m.name)).join(', ')}</div>`:''}${p.kind==='campaign'?`<p class="small">Voluntary participation${meta.endsOn?' · Until '+esc(fmt(meta.endsOn)):''}</p>`:''}${p.kind==='story'&&subject?`<p class="small">Featuring ${esc(subject)} · Shared with their opt-in</p>`:''}${p.images.length?`<div class="post-images">${p.images.map(src=>`<a href="${esc(src)}" target="_blank" rel="noopener"><img src="${esc(src)}" alt="Image shared in this Connect post" loading="lazy"></a>`).join('')}</div>`:''}${meta.awardId?`<a class="small" href="/api/connect/cards/${esc(meta.awardId)}" download>Download recognition card ↓</a>`:''}<div class="post-footer">${state.init.employee?`<button class="reaction ${p.myReaction==='Appreciate'?'selected':''}" data-action="react" data-id="${p.id}" data-reaction="Appreciate">♡ Appreciate${p.reactions.Appreciate?' · '+p.reactions.Appreciate:''}</button><select class="reaction-picker" aria-label="More positive reactions" data-reaction-id="${p.id}"><option value="">More reactions</option>${options(state.init.reactions.filter(x=>x!=='Appreciate'),p.myReaction)}</select>`:''}${Object.entries(p.reactions).filter(([r])=>r!=='Appreciate').map(([r,count])=>`<span class="small">${icons[r]||'✦'} ${esc(r)} · ${count}</span>`).join('')}<button class="comment-toggle" data-action="comments" data-id="${p.id}">Comments${p.commentCount?' · '+p.commentCount:''}</button>${state.init.employee&&p.subjectId&&p.subjectId!==state.init.employee.id?`<button class="quiet" data-action="appreciate" data-employee="${esc(p.subjectId)}">Send appreciation</button>`:''}</div><div class="comments" data-comments="${p.id}" hidden></div><div class="post-menu">${state.init.employee?`<button class="quiet" data-action="report" data-id="${p.id}">Report</button>`:''}${p.canRemove?`<button class="quiet" data-action="remove-post" data-id="${p.id}" data-version="${p.version}">Remove</button>`:''}</div></article>`}
function spotlightBox(){const i=state.init,published=i.spotlight.filter(x=>x.period===i.spotlight[0]?.period);return `<section class="card spotlight-card"><div class="spotlight-mark" aria-hidden="true">✧</div><span class="connect-kicker">MEANINGFUL CONTRIBUTION</span><h2>Monthly Spotlight</h2>${published.length?`<p class="small">${esc(fmt(published[0].period))}</p>${published.slice(0,4).map(s=>`<div class="spotlight-person">${avatar(s.employeeId,s.name)}<div><small>${esc(s.category)}</small><strong>${esc(s.name)}</strong><a href="/connect?post=${s.postId}">Read their story →</a></div></div>`).join('')}`:'<p class="aside-empty">Our next spotlight starts with a meaningful nomination. Recipients appear after P&C reviews and publishes the month.</p>'}${i.employee&&i.periods.length?'<button class="full-button" data-action="nominate">Nominate a colleague ✦</button>':i.admin?'<a class="small" href="/admin/connect">Manage nomination periods →</a>':''}<p class="mood-note">Thoughtful evidence, reviewed fairly. No live popularity ranking.</p></section>`}
function moodBox(){const f=state.init.sharedFeeling;return `<section class="card mood-card"><div class="pulse-intro"><span class="connect-kicker">TODAY’S PULSE</span><h2>${f?'Thanks for checking in today.':'How are you feeling today?'}</h2><p class="mood-note">Your name, photo and feeling are shared with signed-in IUC colleagues. Optional, and never part of MPC.</p></div><div class="pulse-choices"><div class="mood-options">${moods.map(([m,e])=>`<button data-action="pulse" data-mood="${m}" aria-pressed="${f?.mood===m}" class="${f?.mood===m?'selected':''}"><span aria-hidden="true">${e}</span>${m}</button>`).join('')}</div><div class="pulse-foot"><span>${f?'You can change your feeling at any time today.':'Share how your day is going.'}</span>${f?`<button class="quiet" data-action="mood">Add a note</button><button class="quiet" data-action="withdraw-feeling" data-id="${esc(f.postId)}" data-version="${f.version}">Withdraw</button>`:''}</div><span id="pulse-message" role="status"></span></div></section>`}
function actionBox(){return `<section class="card voice-action-card"><span class="connect-kicker">YOUR VOICE, REAL ACTION</span><h2>You Said → We Did</h2>${state.init.actions.length?state.init.actions.slice(0,3).map(v=>`<article class="voice-mini"><span class="label">YOU SAID</span><p>${esc(v.youSaid)}</p><span class="label">WE DID</span><p>${esc(v.weDid)}</p><span class="status-chip">${esc(v.status)}</span></article>`).join(''):'<p class="aside-empty">Ideas deserve a response. Community updates will appear here when P&C shares a progress update or outcome.</p>'}${state.init.employee?'<button class="full-button" data-action="voice-history">Ideas, feedback & responses →</button>':''}</section>`}
async function community(){const b=await api('feed');state.feed=b.posts;state.next=b.next;const ann=!root.dataset.home&&b.announcements.length?`<section class="card"><span class="connect-kicker">OFFICIAL IUC ANNOUNCEMENTS</span>${b.announcements.map(a=>`<details><summary><strong>${esc(a.title)}</strong> <span class="small">· ${esc(a.category)}</span></summary><p class="post-body">${esc(a.body)}</p></details>`).join('')}</section>`:'';shell(`<div class="community-grid"><section class="feed-column" aria-label="Community feed">${state.init.employee?`<div class="card compose-card"><div class="compose-top">${avatar(state.init.employee.id,state.init.employee.name)}<button class="compose-prompt" data-action="compose">What’s a moment worth sharing?</button></div><div class="compose-actions"><button data-action="compose">▧ Share a moment</button><button data-action="appreciate">✦ Appreciate</button><button data-action="recognition">♡ My recognition</button></div></div>`:''}${ann}<div id="community-posts">${state.feed.length?state.feed.map(postCard).join(''):empty('Every connection starts somewhere','Celebrate a small win, share what you learned or thank someone who helped you.',state.init.employee?'<button class="primary" data-action="compose">Share the first moment</button>':'')}</div>${root.dataset.home&&state.feed.length>3?'<button class="feed-more" data-action="expand-feed">More moments ↓</button>':''}<div class="feed-load" ${root.dataset.home&&state.feed.length>3?'hidden':''}>${b.next?'<button data-action="load-feed">More moments ↓</button>':''}</div><button class="guideline-link quiet" data-action="guidelines">Community guidelines</button>${state.init.employee?'<button class="preferences-link quiet" data-action="preferences">Sharing preferences</button>':''}</section><aside class="community-aside">${state.init.employee&&!root.dataset.home?moodBox():''}${spotlightBox()}${state.init.surveys.filter(s=>!s.submitted||pendingTicket('survey'+s.id)).slice(0,1).map(s=>`<section class="card"><span class="connect-kicker">A SMALL QUESTION, A BIG DIFFERENCE</span><h2>Your perspective matters.</h2><p class="small">${esc(s.title)} · Optional</p><button class="full-button" data-action="survey" data-id="${s.id}">Share your perspective →</button></section>`).join('')}${state.init.celebrations.length?`<section class="card"><span class="connect-kicker">LITTLE MOMENTS TO CELEBRATE</span><h2>Today at IUC</h2>${state.init.celebrations.map(c=>`<div class="celebration">${avatar(c.employeeId,c.name)}<div><p>${esc(c.name)}</p><small>${esc(c.type)}${c.years?' · '+c.years+' years':''}</small>${state.init.employee&&c.employeeId!==state.init.employee.id?`<button class="quiet" data-action="appreciate" data-employee="${esc(c.employeeId)}">Send a kind word</button>`:''}</div></div>`).join('')}</section>`:''}${actionBox()}</aside></div>`);const selected=url.searchParams.get('post');if(selected){try{$('#community-posts').classList.add('expanded');const p=state.feed.find(p=>p.id===selected)||await api('posts/'+selected);if(!state.feed.some(x=>x.id===p.id)){$('#community-posts').insertAdjacentHTML('afterbegin',postCard(p));state.feed.unshift(p)}$('[data-post="'+p.id+'"]').scrollIntoView({block:'center',behavior:'smooth'});}catch(e){toast(e.message)}}}
async function impact(){if(!state.init.employee)return community();const b=await api('impact'),values=[...new Set(b.recognition.map(r=>r.value).filter(Boolean))];shell(`<div class="impact-top"><section class="card"><span class="connect-kicker">YOUR CONTRIBUTIONS MATTER</span><h2>My Impact</h2><p>Good work leaves a mark on people. Here are the moments colleagues chose to appreciate.</p><div class="impact-values">${values.length?values.map(v=>`<span class="value-chip">${esc(v)}</span>`).join(''):'<p class="small">CATALYST values will appear here when colleagues recognise them.</p>'}</div></section><section class="card spotlight-card"><span class="connect-kicker">YOUR MONTHLY SPOTLIGHT</span><h2>A contribution worth celebrating.</h2>${b.awards.length?b.awards.map(a=>`<div class="selection"><strong>${esc(a.category)}</strong><span class="small">${esc(fmt(a.period))}</span><p>${esc(a.citation)}</p><a href="/api/connect/cards/${a.id}" download>Download card ↓</a></div>`).join(''):'<p class="small">Published monthly awards will be kept here. Every sincere appreciation is meaningful, with or without an award.</p>'}</section></div>${b.badges.length?`<section><h2 class="panel-title">Badges earned</h2><div class="badge-grid">${b.badges.map(a=>`<article class="badge"><span aria-hidden="true">✦</span><h3>${esc(a.title)}</h3><p class="small">${esc(a.criteria)}</p><p>${esc(a.reason)}</p>${a.reward?`<p class="small">Acknowledgement: ${esc(a.reward)}</p>`:''}<span class="small">${esc(fmt(a.created_at))}</span></article>`).join('')}</div></section>`:''}<section class="card"><span class="connect-kicker">YOUR RECOGNITION TIMELINE</span><h2>Someone appreciated you.</h2>${b.recognition.length?b.recognition.map(r=>`<article class="impact-message"><span class="value-chip">${esc(r.category)}</span><blockquote>“${esc(r.reason)}”</blockquote><span class="small">From ${esc(r.from)} · ${esc(fmt(r.createdAt))}${r.value?' · '+esc(r.value):''}</span></article>`).join(''):empty('Your story is still growing','Appreciation you receive will appear here. You can make someone else’s day right now.','<button class="primary" data-action="appreciate">Appreciate a colleague</button>')}</section>`)}
async function voicePage(){const b=state.init.employee?await api('voice'):{submissions:[]};shell(`<div class="voice-grid"><section class="card"><span class="connect-kicker">YOUR VOICE</span><h2>Make life at IUC better.</h2><p>Have an idea, a useful improvement or something you want P&C to hear? You can share with your name or anonymously.</p><button class="primary" data-action="voice-form">Share your voice ◇</button><p class="small">Salary letters, personal employment queries and confidential casework belong in the <a href="/employee/requests">HR Service Desk</a>.</p></section><section class="card"><span class="connect-kicker">ANONYMOUS FOLLOW-UP</span><h2>Check your private receipt.</h2><p class="small">An anonymous receipt lets you see the response without linking your idea to your employee profile. Keep it private.</p><form data-form="receipt">${field('Private receipt code','receipt','text','required minlength="64" maxlength="64" autocomplete="off"')}<p class="form-error error" role="alert"></p><button class="primary" type="submit">Check response</button></form></section></div><div class="privacy-box">${esc(state.init.privacy)}</div><section class="card voice-history"><span class="connect-kicker">YOUR NAMED SUBMISSIONS</span><h2>A conversation with P&C</h2>${b.submissions.length?b.submissions.map(v=>`<article><span class="status-chip">${esc(v.status)}</span><h3>${esc(v.subject)}</h3><p>${esc(v.body)}</p><p class="small">${esc(v.category)} · ${esc(fmt(v.period))}</p>${v.response?`<div class="privacy-box"><strong>P&C response</strong><p>${esc(v.response)}</p></div>`:'<p class="small">Your submission is with P&C.</p>'}</article>`).join(''):'<p class="small">Your named submissions and responses will appear here. Anonymous submissions are available only through their private receipt.</p>'}</section>${actionBox()}`)}
function checklist(name,title){return `<details class="colleague-picker"><summary>${esc(title)}</summary><input type="search" placeholder="Find a colleague…" aria-label="Find a colleague" data-colleague-search><div class="colleague-choices">${state.init.colleagues.map(e=>`<label class="check-label" data-search="${esc((e.name+' '+e.department).toLowerCase())}"><input name="${name}" value="${esc(e.id)}" type="checkbox">${esc(e.name)}<small>${esc(e.department)}</small></label>`).join('')}</div></details>`}
function composer(){if(!state.init.employee)return;modal('Share a moment',`<p class="dialog-intro">Small wins, learning, team achievements and good moments belong here.</p><form data-form="post">${textarea('What would you like to share?','body',3000)}${select('Who can see this?','visibility',options(['Everyone','Department','Team','Selected colleagues']))}<div id="selected-audience" hidden>${checklist('recipients','Choose who sees this post')}</div>${checklist('mentions','Mention colleagues in this audience')}<label class="field">Images · optional, up to 3<input name="images" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="small">Images are resized and stored privately. Share workplace-safe content; protect confidential information.</p>${formTail('Share moment')}</form>`)}
function appreciation(id=''){if(!state.init.employee)return;const i=state.init;modal('Make Someone’s Day',`<p class="dialog-intro">Tell a colleague what they did and why it made a difference.</p><form data-form="recognition">${select('Who would you like to appreciate?','recipientId',colleagues(id), 'required')}${select('What made them awesome?','category',options(i.recognitionCategories))}${select('CATALYST value · optional','value','<option value="">Choose a value, if relevant</option>'+options(i.values))}${textarea('Tell them why they made a difference','reason')}${select('Sharing','visibility',options(['Everyone','Private']))}${i.stars.enabled?select('Optional stars · '+i.stars.available+' available this month','stars',Array.from({length:Math.min(i.stars.available,i.stars.recipientCap)+1},(_,v)=>`<option value="${v}">${v===0?'No stars · appreciation matters on its own':v+' star'+(v===1?'':'s')}</option>`).join('')):''}<p class="small">Private appreciation is visible to you, the recipient and authorised P&C moderation. It never changes MPC scores.</p>${formTail('Send appreciation ✦')}</form>`)}
function nomination(){if(!state.init.employee)return;if(!state.init.periods.length){modal('Monthly nominations',empty('The next spotlight is on its way','P&C will open a nomination period. You can still appreciate a colleague today.','<button data-action="appreciate" class="primary">Send appreciation</button>'));return}const p=state.init.periods[0];modal('Who made a difference?',`<p class="dialog-intro">Share a specific example. Meaningful contributions matter more than popularity.</p><form data-form="nomination">${select('Month','period',options(state.init.periods.map(p=>p.period)), 'id="nomination-period"')}${select('Category','category',options(p.categories),'id="nomination-category"')}${select('Who would you like to nominate?','recipientId',colleagues(),'required')}${textarea('Tell us why they deserve recognition','reason')}${select('CATALYST value · optional','value','<option value="">If relevant</option>'+options(state.init.values))}<p class="small">Nominations remain with P&C for review. We do not show live nominee counts or rankings.</p>${formTail('Submit nomination')}</form>`)}
function moodDialog(m=''){if(!state.init.employee)return;const f=state.init.sharedFeeling,selected=m||f?.mood||'';modal('How are you feeling today?',`<p class="dialog-intro">Let your colleagues know how you feel. There is no right answer.</p><form data-form="feeling" ${f?`data-id="${esc(f.postId)}" data-version="${f.version}"`:''}>${select('Today I feel…','mood','<option value="">Choose your feeling…</option>'+moods.map(([v,e])=>`<option value="${v}" ${selected===v?'selected':''}>${e} ${v}</option>`).join(''),'required')}${textarea('Message to colleagues · optional','message',800,false,f?.message||'')}<div class="privacy-box"><strong>Visible to all signed-in IUC colleagues</strong><p>Your name, photo, selected feeling and any message will appear in the Community feed. This is a named update. You can update or withdraw your post.</p></div>${formTail(f?'Update shared feeling':'Share with colleagues')}</form>`)}
function surveyDialog(id){const s=state.init.surveys.find(s=>s.id===id);if(!s)return;if(s.submitted&&!pendingTicket('survey'+s.id)){toast('This pulse allows one submission per colleague. Your participation has already started.');return}modal(s.title,`<form data-form="survey" data-survey="${s.id}"><p class="dialog-intro">Participation is optional. Please avoid identifying details in comments.</p>${s.questions.map(q=>`<fieldset class="survey-question"><legend>${esc(q.label)}${q.required?'':' · optional'}</legend>${q.type==='Open text'?`<textarea name="${q.id}" maxlength="1000" rows="3"></textarea>`:`<div class="survey-options">${q.options.map(o=>`<label><input type="radio" name="${q.id}" value="${esc(o)}" required>${esc(o)}</label>`).join('')}</div>`}</fieldset>`).join('')}<div class="privacy-box">${esc(state.init.privacy)}</div>${formTail('Share my perspective')}</form>`)}
function voiceDialog(){if(!state.init.employee)return;modal('Your Voice',`<form data-form="voice">${select('How would you like to share?','sharing',options(['With my name','Anonymously']))}${select('Category','category',options(state.init.voiceCategories))}${field('What is it about?','subject','text','required maxlength="120"')}${textarea('Your idea, suggestion or feedback','body',3000)}<div class="privacy-box" id="voice-privacy">Named submissions are private between you and P&C. A community update is published only as a separate P&C summary.</div><p class="small">Confidential personal employment matters: <a href="/employee/requests">use the HR Service Desk</a>.</p>${formTail('Share with P&C')}</form>`)}
function preferences(){const p=state.init.preferences;modal('Your sharing preferences',`<form data-form="preferences"><p class="dialog-intro">Employee birthdays are displayed automatically to signed-in IUC colleagues, without ages or birth years. Choose your other sharing preferences below.</p>${[['anniversary','Show my work anniversary'],['stories','Allow P&C to feature my agreed employee story'],['notifications','Receive optional Connect notifications in Nadi and by email']].map(([k,l])=>`<label class="check-label"><input name="${k}" type="checkbox" ${p[k]?'checked':''}>${l}</label>`).join('')}<p class="small">Turning off work anniversaries removes them from future community displays. Featured stories need this opt-in and a story agreed with P&C.</p>${formTail('Save preferences')}</form>`)}
function pendingTicket(key){const storedKey='nadi-connect-ticket:'+state.init.employee?.id+':'+day()+':'+key;let b=state.tickets.get(key);if(!b){try{b=JSON.parse(sessionStorage.getItem(storedKey)||'null')}catch{}}if(b&&/^[a-f0-9]{64}$/.test(b.token)&&Date.parse(b.expiresAt)>Date.now()){state.tickets.set(key,b);return b}state.tickets.delete(key);try{sessionStorage.removeItem(storedKey)}catch{}return null}
function clearTicket(key){state.tickets.delete(key);try{sessionStorage.removeItem('nadi-connect-ticket:'+state.init.employee?.id+':'+day()+':'+key)}catch{}}
async function ticket(type,surveyId){const key=type+(surveyId||''),existing=pendingTicket(key);if(existing)return existing.token;const b=await api('tickets','POST',{type,...(surveyId?{surveyId}:{})});state.tickets.set(key,b);try{sessionStorage.setItem('nadi-connect-ticket:'+state.init.employee?.id+':'+day()+':'+key,JSON.stringify({token:b.token,expiresAt:b.expiresAt}))}catch{}return b.token;}
async function resizeImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)throw Error('Choose a JPEG, PNG or WebP below 15 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.84));}
function downloadText(filename,text){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
async function refresh(){state.init=await api('init');if(root.dataset.home){const previous=state.view;state.view='community';await community();if(previous==='impact'){state.homeDialog='My recognition';await impact()}else if(previous==='voice'){state.homeDialog='Ideas, feedback & responses';await voicePage()}return;}if(adminPage)await admin();else if(insightsPage)await insights();else if(state.view==='impact')await impact();else if(state.view==='voice')await voicePage();else await community();}

async function handleForm(form){const d=new FormData(form),get=k=>d.get(k),type=form.dataset.form;
if(type==='post'){const files=[...$('input[name="images"]',form).files];if(files.length>3)throw Error('Choose at most three images.');const images=await Promise.all(files.map(resizeImage));let p=form.dataset.createdPost?{id:form.dataset.createdPost}:await api('posts','POST',{body:get('body'),visibility:get('visibility'),recipients:d.getAll('recipients'),mentions:d.getAll('mentions')});form.dataset.createdPost=p.id;let imageError=false;for(const image of images){const r=await fetch('/api/connect/posts/'+p.id+'/images',{method:'POST',headers:{'content-type':'image/jpeg'},body:image});if(!r.ok)imageError=true}dialog.close();toast(imageError?'Your moment was shared. Some images could not upload.':'Your moment has been shared.');await refresh();}
else if(type==='recognition'){await api('recognition','POST',{recipientId:get('recipientId'),category:get('category'),value:get('value'),reason:get('reason'),visibility:get('visibility'),stars:Number(get('stars')||0)});dialog.close();toast('You just made someone’s day. ✦');await refresh();}
else if(type==='nomination'){await api('nominations','POST',{period:get('period'),category:get('category'),recipientId:get('recipientId'),reason:get('reason'),value:get('value')});dialog.close();toast('Thank you. Your nomination is with P&C for review.');}
else if(type==='feeling'){await api('feeling','POST',{mood:get('mood'),message:get('message'),shareWithColleagues:true,...(form.dataset.id?{postId:form.dataset.id,version:Number(form.dataset.version)}:{})});dialog.close();toast('Your feeling is now visible to IUC colleagues.');await refresh();}
else if(type==='survey'){const id=form.dataset.survey,s=state.init.surveys.find(s=>s.id===id);await api('survey-response','POST',{token:await ticket('survey',id),surveyId:id,answers:Object.fromEntries(s.questions.map(q=>[q.id,get(q.id)||'']))});clearTicket('survey'+id);dialog.close();toast('Thank you for sharing your perspective.');await refresh();}
else if(type==='voice'){const anonymous=get('sharing')==='Anonymously',b={anonymous,category:get('category'),subject:get('subject'),body:get('body')};if(anonymous)b.token=await ticket('voice');const r=await api('voice','POST',b);clearTicket('voice');if(anonymous){state.receipt=r.receipt;modal('Your voice has been received.',`<p class="dialog-intro">Save this private receipt to see P&C’s response. We cannot recover it through your employee account.</p><div class="receipt">${esc(r.receipt)}</div><div class="form-actions"><button data-action="download-receipt">Download receipt</button><button data-action="copy-receipt">Copy receipt</button><button class="primary" data-action="close-dialog">Done</button></div>`)}else{dialog.close();toast('Your idea is with P&C. Thank you for sharing.')}await refresh();}
else if(type==='receipt'){const v=await api('voice-receipt','POST',{receipt:get('receipt')});modal('Your anonymous follow-up',`<span class="status-chip">${esc(v.status)}</span><h3>${esc(v.subject)}</h3><p class="post-body">${esc(v.body)}</p>${v.response?`<div class="privacy-box"><strong>P&C response</strong><p class="post-body">${esc(v.response)}</p></div>`:'<p class="small">Your feedback is with P&C. Check again using the same receipt.</p>'}`)}
else if(type==='preferences'){await api('preferences','PATCH',Object.fromEntries(['anniversary','stories','notifications'].map(k=>[k,d.has(k)])));dialog.close();toast('Your preferences are saved.');await refresh();}
else if(type==='comment'){await api('posts/'+form.dataset.id+'/comments','POST',{body:get('body')});form.reset();await loadComments(form.dataset.id);await updatePost(form.dataset.id);}
else if(type==='report'){await api('posts/'+form.dataset.id+'/report','POST',{reason:get('reason'),...(form.dataset.comment?{commentId:form.dataset.comment}:{})});dialog.close();toast('Your report is with P&C. Thank you.');}
else if(type==='remove'){await api('posts/'+form.dataset.id,'DELETE',{version:Number(form.dataset.version),reason:get('reason')||''});dialog.close();toast('The post has been removed.');await refresh();}
else if(type==='remove-comment'){await api('comments/'+form.dataset.id,'DELETE',{version:Number(form.dataset.version),reason:get('reason')||''});dialog.close();await loadComments(form.dataset.post);await updatePost(form.dataset.post);toast('Comment removed.');}
else await handleAdminForm(form,d);
}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-form]'))return;e.preventDefault();const btn=$('button[type="submit"]',f),error=$('.form-error',f);if(btn?.disabled)return;if(error)error.textContent='';if(btn)btn.disabled=true;try{await handleForm(f)}catch(x){if(error)error.textContent=x.message;else toast(x.message)}finally{if(btn)btn.disabled=false}});
async function updatePost(id){const p=await api('posts/'+id),at=state.feed.findIndex(p=>p.id===id);if(at>=0)state.feed[at]=p;const article=$('[data-post="'+id+'"]');if(article){const old=$('[data-comments]',article),open=old&&!old.hidden,content=old?.innerHTML;article.outerHTML=postCard(p);if(open){const c=$('[data-comments="'+id+'"]');c.hidden=false;c.innerHTML=content}}}
async function loadComments(id){const b=await api('posts/'+id+'/comments'),c=$('[data-comments="'+id+'"]');if(!c)return;c.hidden=false;c.innerHTML=b.comments.reverse().map(x=>`<article class="comment"><strong>${esc(x.author)}</strong><p>${esc(x.body)}</p><span class="small">${esc(fmt(x.createdAt))}</span>${x.canRemove?`<button class="quiet" data-action="remove-comment" data-id="${x.id}" data-version="${x.version}" data-post="${id}">Remove</button>`:''}${state.init.employee?`<button class="quiet" data-action="report" data-id="${id}" data-comment="${x.id}">Report</button>`:''}</article>`).join('')+(state.init.employee?`<form class="comment-form" data-form="comment" data-id="${id}"><input name="body" placeholder="Add a thoughtful comment…" maxlength="800" required aria-label="Your comment"><button type="submit">Send</button><span class="form-error error" role="alert"></span></form>`:'');}
document.addEventListener('input',e=>{if(e.target.matches('[data-colleague-search]')){$$('[data-search]',e.target.closest('.colleague-picker')).forEach(l=>l.hidden=!l.dataset.search.includes(e.target.value.toLowerCase()))}});
document.addEventListener('change',async e=>{try{if(e.target.matches('[name="visibility"]')){$('#selected-audience').hidden=e.target.value!=='Selected colleagues'}if(e.target.id==='nomination-period')$('#nomination-category').innerHTML=options(state.init.periods.find(p=>p.period===e.target.value).categories);if(e.target.matches('[name="sharing"]'))$('#voice-privacy').textContent=e.target.value==='Anonymously'?state.init.privacy+' You receive a private receipt for follow-up.':'Named submissions are private between you and P&C. A community update is a separate P&C summary.';if(e.target.matches('[data-reaction-id]')&&e.target.value){const p=state.feed.find(p=>p.id===e.target.dataset.reactionId),value=e.target.value;await api('posts/'+p.id+'/reaction','POST',{reaction:p.myReaction===value?null:value});await updatePost(p.id)}if(e.target.id==='review-period')await renderReview(e.target.value);if(e.target.id==='insights-period'||e.target.id==='insights-department')await renderInsights();if(e.target.matches('[data-award-category]')){$('#selection-scores').innerHTML=scoreInputs(e.target.value)}if(e.target.matches('[data-question-type]'))e.target.parentElement.querySelector('[data-question-options]').hidden=e.target.value!=='Multiple choice';}catch(x){toast(x.message)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;try{if(a==='expand-feed'){$('#community-posts').classList.add('expanded');b.hidden=true;$('.feed-load').hidden=false;return}if(!state.init)return toast('Your workspace is still loading. Please try again.');if(a==='pulse'){if(state.pulseSaving)return;state.pulseSaving=true;const f=state.init.sharedFeeling;$$('[data-action="pulse"]').forEach(x=>x.disabled=true);try{await api('feeling','POST',{mood:b.dataset.mood,message:f?.message||'',shareWithColleagues:true,...(f?{postId:f.postId,version:f.version}:{})});await refresh();toast('Thanks for checking in today.')}catch(error){await refresh().catch(()=>{});throw error}finally{state.pulseSaving=false;$$('[data-action="pulse"]').forEach(x=>x.disabled=false)}}else if(a==='recognition'){state.homeDialog='My recognition';await impact()}else if(a==='voice-history'){state.homeDialog='Ideas, feedback & responses';await voicePage()}else if(a==='close-dialog')dialog.close();else if(a==='compose')composer();else if(a==='appreciate')appreciation(b.dataset.employee||'');else if(a==='nominate')nomination();else if(a==='mood')moodDialog(b.dataset.mood||'');else if(a==='withdraw-feeling')modal('Withdraw your shared feeling?',`<form data-form="remove" data-id="${b.dataset.id}" data-version="${b.dataset.version}"><p>Your feeling and any message will no longer appear to colleagues in the Community feed.</p>${formTail('Withdraw feeling')}</form>`);else if(a==='voice-form')voiceDialog();else if(a==='survey')surveyDialog(b.dataset.id);else if(a==='preferences')preferences();else if(a==='privacy')modal('Your privacy matters',`<p class="privacy-box">${esc(state.init.privacy)}</p><p class="small">Daily feeling updates show your name, photo and selected feeling to all signed-in IUC colleagues. Previously anonymous check-ins remain anonymous. Anonymous pulse surveys use a separate process and a minimum reporting threshold.</p>`);else if(a==='guidelines')modal('Our community guidelines',`<ul class="guidelines"><li><strong>Be kind.</strong> Encourage and appreciate others.</li><li><strong>Be respectful.</strong> Make space for different experiences.</li><li><strong>Celebrate others.</strong> Describe specific contributions.</li><li><strong>Protect confidential information.</strong> Keep personal, salary, student and case details out of community posts.</li><li><strong>Keep it professional.</strong> Share appropriate workplace content.</li></ul><p class="small">Report a post or comment for P&C review. Personal HR questions and confidential employment issues belong in the <a href="/employee/requests">HR Service Desk</a>.</p>`);else if(a==='notifications'){const r=await api('notifications');modal('Your Connect inbox',r.notifications.length?r.notifications.map(n=>`<div class="notification ${!n.read_at?'unread':''}"><a href="${esc(n.link)}">${esc(n.message)}</a><time>${esc(fmt(n.created_at))}</time></div>`).join(''):'<p class="small">Recognition and community updates will appear here when relevant to you.</p>');await api('notifications','PATCH',{});const badge=$('#notification-count');if(badge)badge.hidden=true;}else if(a==='copy-receipt'){await navigator.clipboard.writeText(state.receipt);toast('Private receipt copied. Keep it safe.')}else if(a==='download-receipt')downloadText('Nadi-Connect-private-receipt.txt','Nadi Connect — anonymous Your Voice receipt\n\nKeep this code private.\n'+state.receipt+'\n\nOpen /connect?view=voice to check the response.\n');else if(a==='react'){const p=state.feed.find(p=>p.id===b.dataset.id);await api('posts/'+p.id+'/reaction','POST',{reaction:p.myReaction===b.dataset.reaction?null:b.dataset.reaction});await updatePost(p.id)}else if(a==='comments'){const c=$('[data-comments="'+b.dataset.id+'"]');if(c&&!c.hidden)c.hidden=true;else await loadComments(b.dataset.id)}else if(a==='report')modal('Report for P&C review',`<form data-form="report" data-id="${b.dataset.id}" ${b.dataset.comment?'data-comment="'+b.dataset.comment+'"':''}><p class="dialog-intro">Your report is private to P&C. Explain the concern respectfully.</p>${textarea('Why should P&C review this?','reason')}${formTail('Send report')}</form>`);else if(a==='remove-post')modal('Remove your post?',`<form data-form="remove" data-id="${b.dataset.id}" data-version="${b.dataset.version}"><p>The post and its images will no longer appear in the community. Moderation records follow the retention policy.</p>${state.init.admin?textarea('Removal reason · required for another employee’s post','reason',1500,false):''}${formTail('Remove post')}</form>`);else if(a==='remove-comment')modal('Remove this comment?',`<form data-form="remove-comment" data-id="${b.dataset.id}" data-post="${b.dataset.post}" data-version="${b.dataset.version}"><p>This comment will no longer appear in the discussion.</p>${state.init.admin?textarea('Removal reason · required for another employee’s comment','reason',1500,false):''}${formTail('Remove comment')}</form>`);else if(a==='load-feed'){$('#community-posts').classList.add('expanded');b.disabled=true;const r=await api('feed?before='+encodeURIComponent(state.next));state.feed.push(...r.posts);$('#community-posts').insertAdjacentHTML('beforeend',r.posts.map(postCard).join(''));state.next=r.next;if(!r.next)b.remove();else b.disabled=false;}else await adminAction(a,b);}catch(x){state.homeDialog=null;toast(x.message);b.disabled=false}});

async function admin(){state.admin=await api('admin/init');shell(`<div class="admin-tabs" aria-label="P&C Connect functions">${[['spotlight','Monthly Spotlight'],['voice','Employee Voice'],['surveys','Pulse surveys'],['features','Stories & campaigns'],['badges','Badges & rewards'],['moderation','Moderation'],['insights','Insights'],['settings','Settings']].map(([key,label])=>`<button data-action="admin-tab" data-tab="${key}" class="${state.adminTab===key?'selected':''}">${label}</button>`).join('')}</div><div id="admin-panel"></div>`);await adminPanel();}
async function adminPanel(){const p=$('#admin-panel'),a=state.admin;if(state.adminTab==='spotlight'){p.innerHTML=`<div class="connect-toolbar"><h2>Monthly Spotlight</h2><button class="primary" data-action="open-period">Open nominations</button>${a.periods.length?`<label>Month<select id="review-period">${options(a.periods.map(p=>p.period),state.review?.period?.period)}</select></label>`:''}</div><div id="spotlight-review"></div>`;await renderReview(state.review?.period?.period||a.periods[0]?.period||month());}
else if(state.adminTab==='voice'){p.innerHTML=`<section class="card"><span class="connect-kicker">LISTEN AND RESPOND</span><h2>Employee Voice</h2><p class="small">Anonymous entries show no employee identity or exact submission time. Publish a separate, safe action summary; do not copy identifying text into community updates.</p>${a.voices.length?a.voices.map(v=>`<article class="report-card"><span class="status-chip">${esc(v.status)}</span><h3>${esc(v.subject)}</h3><span class="small">${v.anonymous?'Anonymous · receipt follow-up':esc(v.employee_name||'Employee')} · ${esc(v.category)} · ${esc(fmt(v.period))}</span><blockquote>${esc(v.body)}</blockquote>${v.response?`<p class="small">Current response: ${esc(v.response)}</p>`:''}<button data-action="respond-voice" data-id="${v.id}">Respond & update</button></article>`).join(''):empty('Listening starts here','Employee ideas and feedback will appear here. Anonymous identity is not available through this interface.')}</section>`}
else if(state.adminTab==='surveys'){p.innerHTML=`<section class="card"><div class="admin-subhead"><div><span class="connect-kicker">OCCASIONAL, VOLUNTARY, USEFUL</span><h2>Pulse surveys</h2></div><button class="primary" data-action="create-survey">Create a pulse</button></div><p class="small">Use a short pulse or a survey of up to 12 questions. Answers are anonymous; reports show thresholded choice totals. Open text is collected but is excluded from routine reports.</p>${a.surveys.map(s=>`<article class="report-card"><span class="status-chip">${esc(s.status)}</span><h3>${esc(s.title)}</h3><p class="small">${esc(fmt(s.starts_on))}–${esc(fmt(s.ends_on))} · ${s.questions.length} questions</p>${s.status==='Published'?`<button data-action="close-survey" data-id="${s.id}" data-version="${s.version}">Close survey</button>`:''}</article>`).join('')||'<p class="small">No pulse published yet. Keep invitations occasional to avoid survey fatigue.</p>'}</section>`}
else if(state.adminTab==='features'){p.innerHTML=`<div class="admin-grid"><section class="card"><span class="connect-kicker">PEOPLE OF IUC</span><h2>Stories worth sharing.</h2><p>Celebrate real people, projects and learning. Feature only an employee who has opted in and agreed to the story.</p><button class="primary" data-action="feature-story">Feature an employee</button></section><section class="card"><span class="connect-kicker">SMALL INVITATIONS TO CONNECT</span><h2>Voluntary campaigns</h2><p>Invite appreciation, learning, wellness or CATALYST moments. Participation remains optional.</p><button class="primary" data-action="feature-campaign">Launch a campaign</button></section></div>`}
else if(state.adminTab==='badges'){p.innerHTML=`<section class="card"><div class="admin-subhead"><div><span class="connect-kicker">CRITERIA BEFORE REWARDS</span><h2>Badges & acknowledgements</h2></div><button class="primary" data-action="create-badge">Define a badge</button></div><p class="small">Each badge needs clear criteria and a human reason for issuance. A reward description is an organisation-approved acknowledgement, not an automatic entitlement.</p>${a.badges.map(b=>`<article class="report-card"><h3>✦ ${esc(b.title)}</h3><p>${esc(b.criteria)}</p>${b.reward?`<p class="small">Acknowledgement: ${esc(b.reward)}</p>`:''}<button data-action="issue-badge" data-id="${b.id}">Issue to an employee</button></article>`).join('')||'<p class="small">No badges defined yet.</p>'}</section>`}
else if(state.adminTab==='moderation'){p.innerHTML=`<section class="card"><span class="connect-kicker">A SAFE, RESPECTFUL COMMUNITY</span><h2>Reported content</h2><p class="small">Review context before acting. Every moderation action needs a reason and is recorded. Reporter identities are not shared with the content author.</p>${a.reports.length?a.reports.map(r=>`<article class="report-card"><p class="small">${esc(r.author_name||'P&C')} · ${esc(fmt(r.created_at))}</p><blockquote>${esc(r.comment_body||r.body)}</blockquote><div class="notice">Report: ${esc(r.reason)}</div><div class="report-actions">${['hide','remove','restore'].map(action=>`<button data-action="moderate" data-id="${r.post_id}" data-comment="${r.comment_id||''}" data-version="${r.comment_id?r.comment_version:r.version}" data-mode="${action}">${action[0].toUpperCase()+action.slice(1)} content</button>`).join('')}</div></article>`).join(''):'<p class="small">No open reports. Employees can report a post or comment for P&C review.</p>'}<h3>Hidden content</h3>${(a.hidden||[]).map(r=>`<article class="report-card"><blockquote>${esc(r.comment_body||r.body)}</blockquote><button data-action="moderate" data-id="${r.post_id}" data-comment="${r.comment_id||''}" data-version="${r.comment_id?r.comment_version:r.version}" data-mode="restore">Restore after review</button></article>`).join('')||'<p class="small">No hidden content awaiting a decision.</p>'}<h3>Recent moderation and governance activity</h3><div class="table-scroll"><table><thead><tr><th>Action</th><th>When</th><th>Detail</th></tr></thead><tbody>${a.audit.map(v=>`<tr><td>${esc(v.action.replaceAll('_',' '))}</td><td>${esc(fmt(v.created_at))}</td><td>${esc(JSON.stringify(JSON.parse(v.detail_json)))}</td></tr>`).join('')}</tbody></table></div></section>`}
else if(state.adminTab==='insights'){p.innerHTML=insightControls();await renderInsights();}
else if(state.adminTab==='settings'){p.innerHTML=settingsForm();}
}
async function renderReview(p){state.review=await api('admin/review?period='+encodeURIComponent(p));const r=state.review,t=r.period,el=$('#spotlight-review');if(!t){el.innerHTML=empty('Open a month of appreciation','Choose which categories are active in Settings, then open nominations. Only approved recipients are published.');return}el.innerHTML=`<div class="notice">${esc(fmt(t.period))} · ${esc(t.status)}. Scores support a human decision; they do not select a winner. Monthly stars and nominations never change MPC.</div><div class="connect-toolbar">${t.status==='Open'?'<button class="primary" data-action="close-period">Close nominations & review</button>':t.status==='Review'?'<button class="primary" data-action="select-award">Review & approve a recipient</button><button data-action="publish-spotlight">Publish approved Spotlight</button>':'<a href="/connect">View published celebration →</a>'}</div><div class="admin-grid"><section class="card"><span class="connect-kicker">APPROVED SELECTIONS</span><h2>Ready for the spotlight</h2>${r.selections.length?r.selections.map(s=>`<div class="selection"><strong>${esc(s.category)}</strong><p>${esc(s.employee_name)} · Reviewed score ${s.weighted_score.toFixed(2)} / 5</p><p>${esc(s.citation)}</p><span class="small">Review rationale: ${esc(s.rationale)}</span></div>`).join(''):'<p class="small">No recipients approved yet. Review meaningful evidence and fairness before publishing.</p>'}</section><section class="card"><span class="connect-kicker">FAIRNESS REVIEW</span><h2>Context before conclusions.</h2><p class="small">Patterns are review indicators, never accusations. Consider normal collaboration and department size.</p>${r.flags.length?r.flags.map(f=>`<div class="notice"><strong>${esc(f.type)}</strong><p>${f.employees.map(nameOf).map(esc).join(' · ')}</p><p>${esc(f.detail)}</p></div>`).join(''):'<p class="small">No configured pattern indicators found for this month.</p>'}</section><section class="card admin-wide"><span class="connect-kicker">NOMINATION EVIDENCE</span><h2>Why colleagues made a difference.</h2>${r.nominations.length?r.nominations.map(n=>`<article class="review-evidence"><strong>${esc(n.recipient_name)} · ${esc(n.category)}</strong><p>${esc(n.reason)}</p><span class="small">${esc(n.nominator_name)} · ${esc(n.nominator_department)}${n.value?' · '+esc(n.value):''}</span></article>`).join(''):'<p class="small">No nominations submitted for this month.</p>'}</section><section class="card admin-wide"><span class="connect-kicker">RECOGNITION CONTEXT</span><h2>Appreciation behind the evidence</h2>${r.recognition.length?r.recognition.map(n=>`<article class="review-evidence"><strong>${esc(n.recipient_name)} · ${esc(n.category)}</strong><p>${esc(n.reason)}</p><span class="small">${esc(n.sender_name)} · ${esc(n.sender_department)}${n.value?' · '+esc(n.value):''}</span></article>`).join(''):'<p class="small">No recognition records in this period.</p>'}</section></div>`;}
function scoreInputs(category){const c=state.review.period.categories.find(c=>c.title===category);return `<fieldset><legend>Human review scores · 0 to 5</legend><div class="weights">${criteria.map((v,i)=>`<label>${esc(v)} · ${c.weights[i]}%<input name="score${i}" type="number" min="0" max="5" step="0.1" required></label>`).join('')}</div></fieldset>`}
function settingsForm(){const s=state.admin.settings;return `<form data-form="settings"><section class="card"><span class="connect-kicker">CONNECT GOVERNANCE</span><h2>Settings</h2><div class="form-grid">${field('Minimum respondents · at least 5','threshold','number','required min="5" max="20"',s.threshold)}${field('Named content retention · months','retentionMonths','number','required min="3" max="60"',s.retentionMonths)}${field('Anonymous response retention · months','anonymousRetentionMonths','number','required min="1" max="24"',s.anonymousRetentionMonths)}</div><label class="check-label"><input name="starsEnabled" type="checkbox" ${s.starsEnabled?'checked':''}>Enable optional monthly appreciation stars</label><div class="form-grid">${field('Monthly stars per employee','monthlyStars','number','required min="1" max="50"',s.monthlyStars)}${field('Monthly stars to one colleague','recipientStars','number','required min="1" max="10"',s.recipientStars)}</div><div class="privacy-box">Stars do not determine winners or employment decisions. Reports always protect a minimum of five respondents. No model calls are required for these features.</div></section><section class="card"><h2>Spotlight categories & selection weights</h2><p class="small">Each category totals 100%. Changes apply to newly opened periods; existing periods keep their agreed rubric.</p>${s.categories.map((c,i)=>`<fieldset data-category="${esc(c.title)}"><legend>${esc(c.title)}</legend><label class="check-label"><input name="active${i}" type="checkbox" ${c.active?'checked':''}>Include in new nomination periods</label><div class="weights">${criteria.map((k,j)=>`<label>${esc(k)}<input name="weight${i}_${j}" type="number" min="0" max="100" value="${c.weights[j]}" required></label>`).join('')}</div></fieldset>`).join('')}<p class="form-error error" role="alert"></p><button class="primary" type="submit">Save Connect settings</button></section></form><section class="card"><h3>Apply retention</h3><p class="small">This maintenance action removes old private images, expires anonymous response content and clears old named messages under the saved retention limits. Employee records and MPC history are retained.</p><button data-action="retention">Review retention action</button></section>`}
function questionRow(i){return `<div class="question-row" data-question><label class="field">Question ${i}<input data-question-label maxlength="200" required placeholder="What would you like to ask?"></label><select data-question-type aria-label="Question type">${options(['Likert','Multiple choice','Rating','Yes / No','Open text'])}</select><label class="field" data-question-options hidden>Options · one per line<textarea rows="3" placeholder="First option&#10;Second option"></textarea></label><button class="quiet" type="button" data-action="remove-question">Remove question</button></div>`}
function insightControls(){return `<div class="connect-toolbar"><h2>${adminPage?'Culture & inclusion insights':'Your Connect insights'}</h2><div class="query-controls"><input id="insights-period" aria-label="Reporting month" type="month" value="${month()}">${adminPage?`<select id="insights-department" aria-label="Reporting department"><option value="">All IUC</option>${options([...new Set(state.init.colleagues.map(e=>e.department))].sort())}</select>`:''}</div></div><div id="insights-results"></div>`}
async function insights(){shell(insightControls());await renderInsights();}
async function renderInsights(){const p=$('#insights-period').value,dept=$('#insights-department')?.value,b=await api('insights?period='+encodeURIComponent(p)+(dept?'&department='+encodeURIComponent(dept):'')),band=(label,value)=>`<div class="pulse-band"><span>${esc(label)}</span><div class="bar"><i style="width:${Number(value)}%"></i></div><strong>${Number(value)}%</strong></div>`;$('#insights-results').innerHTML=`<p class="small">${esc(b.scope)} · ${esc(fmt(b.period))} · Anonymity threshold: ${b.threshold}</p><div class="insight-grid">${[['Recognition inclusion',b.recognisedPercentage+'%',b.recognisedEmployees+' of '+b.currentEmployees+' current colleagues recognised'],['Recognition participation',b.participationPercentage+'%','Colleagues giving or receiving appreciation'],['Across departments',b.crossDepartmentRecognition,'Appreciations crossing department boundaries'],['Ideas implemented',b.voice?b.voice.implementationPercentage+'%':'—',b.voice?(b.voice.implemented+' of '+b.voice.total+' submissions'):'Voice casework stays with P&C']].map(([title,value,note])=>`<article class="metric"><span>${esc(title)}</span><strong>${esc(value)}</strong><p>${esc(note)}</p></article>`).join('')}</div><div class="privacy-box">${esc(b.inclusionMessage)} Individual moods and anonymous respondent identities are not available in this view.</div><div class="admin-grid"><section class="card"><span class="connect-kicker">VOLUNTARY CHECK-INS</span><h2>Community pulse</h2>${b.mood.suppressed?`<p class="small">${esc(b.mood.message)}</p>`:`${Object.entries(b.mood.bands).map(([k,v])=>band(k,v)).join('')}<p class="small">${b.mood.checkIns} check-ins across ${b.mood.reportedDays} eligible days. Each reported day met the threshold; this is a response total, not a count of distinct people across the month.</p>`}</section><section class="card"><span class="connect-kicker">VALUES IN EVERYDAY ACTION</span><h2>CATALYST recognition</h2>${Object.keys(b.values).length?Object.entries(b.values).map(([k,v])=>`<p><span class="value-chip">${esc(k)}</span> <span class="small">${v} meaningful appreciations</span></p>`).join(''):'<p class="small">Recognised values will appear as appreciation is shared.</p>'}</section>${b.surveys.map(s=>`<section class="card admin-wide"><span class="connect-kicker">ANONYMOUS PULSE</span><h2>${esc(s.title)}</h2>${s.suppressed?`<p class="small">${esc(s.message)}</p>`:s.questions.map(q=>`<h3>${esc(q.label)}</h3>${q.options.map(o=>band(o.label,o.percentage)).join('')}`).join('')}<p class="small">Choice totals only. No individual answers or free text appear here.</p></section>`).join('')}</div>`;}
async function adminAction(a,b){if(a==='admin-tab'){state.adminTab=b.dataset.tab;history.replaceState({},'',location.pathname+'?tab='+state.adminTab);$$('.admin-tabs button').forEach(t=>t.classList.toggle('selected',t.dataset.tab===state.adminTab));await adminPanel();}
else if(a==='open-period')modal('Open monthly nominations',`<form data-form="period">${field('Nomination month','period','month','required',month())}<p class="small">The active categories and weights in Settings are fixed for this period. Employees will be able to submit nominations until you close it.</p>${formTail('Open nominations')}</form>`);
else if(a==='close-period'||a==='publish-spotlight'){const publish=a==='publish-spotlight';modal(publish?'Publish Monthly Spotlight?':'Close nominations?',`<form data-form="period-change" data-mode="${publish?'publish':'close'}"><p>${publish?'Only the approved recipients and public citations will be shared. Check the evidence and fairness indicators before publishing.':'Nominations will close so P&C can review evidence and approve recipients.'}</p>${formTail(publish?'Publish approved recipients':'Close & start review')}</form>`)}
else if(a==='select-award'){const categories=state.review.period.categories.filter(c=>c.active).map(c=>c.title);modal('Review & approve a recipient',`<form data-form="selection">${select('Award category','category',options(categories),'data-award-category')}${select('Recipient','recipientId',colleagues(),'required')}<div id="selection-scores">${scoreInputs(categories[0])}</div>${textarea('Human review rationale · private','rationale')}${textarea('Approved citation · visible to employees','citation',600)}<div class="notice">This action records a human approval. A score does not automatically select a winner. Consider inclusion and the context behind any fairness flags.</div>${formTail('Approve this selection')}</form>`)}
else if(a==='respond-voice'){const v=state.admin.voices.find(v=>v.id===b.dataset.id);modal('Respond to employee voice',`<form data-form="voice-update" data-id="${v.id}" data-version="${v.version}"><p class="dialog-intro">${esc(v.subject)} · ${v.anonymous?'Anonymous':esc(v.employee_name||'Employee')}</p>${select('Progress','status',options(statusLabels,v.status))}${textarea('Private follow-up response','response',2000,true,v.response||'')}${textarea('You Said · public-safe summary, optional','publicSummary',500,false,v.public_summary||'')}${textarea('We Did · public action explanation, optional','publicAction',1000,false,v.public_action||'')}<p class="small">Leave both public fields blank to keep this case out of the community. Never publish identifying details from anonymous feedback.</p>${formTail('Save response & progress')}</form>`)}
else if(a==='create-survey')modal('Create a voluntary pulse',`<form data-form="create-survey">${field('Pulse title','title','text','required maxlength="120"')}<div class="form-grid">${field('Starts on','startsOn','date','required',day())}${field('Ends on','endsOn','date','required',day())}</div><div id="survey-questions">${questionRow(1)}</div><button type="button" data-action="add-question">＋ Add question</button><p class="small">Open text is optional. Individual free text is excluded from routine reports.</p>${formTail('Publish pulse')}</form>`);
else if(a==='add-question'){const n=$$('[data-question]',dialog).length;if(n>=12)throw Error('Use at most 12 questions.');$('#survey-questions').insertAdjacentHTML('beforeend',questionRow(n+1))}else if(a==='remove-question'){if($$('[data-question]',dialog).length===1)throw Error('Keep at least one question.');b.closest('[data-question]').remove()}
else if(a==='close-survey')modal('Close this pulse?',`<form data-form="close-survey" data-id="${b.dataset.id}" data-version="${b.dataset.version}"><p>New responses will stop. Existing aggregate results remain protected by the reporting threshold.</p>${formTail('Close pulse')}</form>`);
else if(a==='feature-story'||a==='feature-campaign'){const story=a==='feature-story';modal(story?'People of IUC':'Launch a voluntary campaign',`<form data-form="feature" data-kind="${story?'story':'campaign'}">${field(story?'Story title':'Campaign title','title','text','required maxlength="120"')}${story?select('Employee · must have opted in','employeeId',colleagues(),'required'):field('Campaign ends','endsOn','date','required',day())}${textarea(story?'Agreed story':'Campaign invitation','body',3000)}<p class="small">${story?'Confirm the employee agreed to this content. Their story preference must be enabled.':'Participation is voluntary. Appreciation, Learning, Wellness and CATALYST are useful campaign themes.'}</p>${formTail(story?'Publish agreed story':'Launch campaign')}</form>`)}
else if(a==='create-badge')modal('Define a meaningful badge',`<form data-form="badge">${field('Badge name','title','text','required maxlength="80"')}${textarea('Clear earning criteria','criteria')}${textarea('Organisation-approved acknowledgement · optional','reward',300,false)}${formTail('Create badge')}</form>`);
else if(a==='issue-badge')modal('Issue a badge',`<form data-form="badge-award" data-id="${b.dataset.id}">${select('Employee','employeeId',colleagues(),'required')}${textarea('How the criteria were met','reason')}${formTail('Issue badge')}</form>`);
else if(a==='moderate')modal('Record a moderation decision',`<form data-form="moderation" data-id="${b.dataset.id}" data-comment="${b.dataset.comment}" data-version="${b.dataset.version}" data-mode="${b.dataset.mode}"><p>Action: <strong>${esc(b.dataset.mode)}</strong>. Review the content and context before acting.</p>${textarea('Reason for this decision','reason')}${formTail('Record & apply')}</form>`);
else if(a==='retention')modal('Apply saved retention rules?',`<form data-form="retention"><p>This removes content older than ${state.admin.settings.retentionMonths} months and anonymous responses older than ${state.admin.settings.anonymousRetentionMonths} months. Expired tickets are cleared. This content removal cannot be undone from this interface.</p><p class="small">Employee Master, MPC and CPD records are retained.</p>${formTail('Apply retention')}</form>`);
}
async function handleAdminForm(f,d){const get=k=>d.get(k),type=f.dataset.form;if(type==='period'){await api('admin/periods','POST',{period:get('period')});state.review=null;toast('Monthly nominations are open.')}else if(type==='period-change'){const t=state.review.period;await api('admin/periods/'+t.period,'PATCH',{version:t.version,action:f.dataset.mode});toast(f.dataset.mode==='publish'?'The approved Spotlight is published.':'Nominations closed. Review is ready.')}else if(type==='selection'){await api('admin/selections','POST',{period:state.review.period.period,version:state.review.period.version,category:get('category'),recipientId:get('recipientId'),scores:criteria.map((_,i)=>Number(get('score'+i))),rationale:get('rationale'),citation:get('citation')});toast('Human selection approval recorded.')}else if(type==='voice-update'){await api('admin/voice/'+f.dataset.id,'PATCH',{version:Number(f.dataset.version),status:get('status'),response:get('response'),publicSummary:get('publicSummary'),publicAction:get('publicAction')});toast('Voice response and progress saved.')}else if(type==='create-survey'){const questions=$$('[data-question]',f).map(r=>({label:$('[data-question-label]',r).value,type:$('[data-question-type]',r).value,options:$('textarea',r).value.split('\n').map(s=>s.trim()).filter(Boolean)}));await api('admin/surveys','POST',{title:get('title'),startsOn:get('startsOn'),endsOn:get('endsOn'),questions});toast('The voluntary pulse is published.')}else if(type==='close-survey'){await api('admin/surveys/'+f.dataset.id,'PATCH',{version:Number(f.dataset.version)});toast('Survey closed.')}else if(type==='feature'){await api('admin/feature','POST',{kind:f.dataset.kind,title:get('title'),body:get('body'),...(f.dataset.kind==='story'?{employeeId:get('employeeId')}:{endsOn:get('endsOn')})});toast('Community feature published.')}else if(type==='badge'){await api('admin/badges','POST',{title:get('title'),criteria:get('criteria'),reward:get('reward')});toast('Badge criteria saved.')}else if(type==='badge-award'){await api('admin/badge-awards','POST',{badgeId:f.dataset.id,employeeId:get('employeeId'),reason:get('reason')});toast('Badge issued with your recorded reason.')}else if(type==='moderation'){await api('admin/moderation','POST',{postId:f.dataset.id,commentId:f.dataset.comment||null,version:Number(f.dataset.version),action:f.dataset.mode,reason:get('reason')});toast('Moderation decision recorded.')}else if(type==='settings'){const data={threshold:Number(get('threshold')),retentionMonths:Number(get('retentionMonths')),anonymousRetentionMonths:Number(get('anonymousRetentionMonths')),starsEnabled:d.has('starsEnabled'),monthlyStars:Number(get('monthlyStars')),recipientStars:Number(get('recipientStars')),categories:state.admin.settings.categories.map((c,i)=>({title:c.title,active:d.has('active'+i),weights:criteria.map((_,j)=>Number(get('weight'+i+'_'+j)))}))};await api('admin/settings','PATCH',{version:state.admin.version,data});toast('Connect settings saved.');await refresh();return;}else if(type==='retention'){await api('admin/retention','POST',{});toast('Saved retention policy applied.')}else throw Error('This form is not available.');dialog.close();await refresh();}
refresh().catch(e=>{for(const id of ['home-spotlight','home-voice']){const slot=document.getElementById(id);if(slot)slot.innerHTML='<p role="status">Community updates are unavailable. Refresh to try again.</p>';}const p=$('#today-pulse');if(p)p.innerHTML='<p role="status">Today’s Pulse is unavailable. Refresh to try again.</p>';root.innerHTML=`<div class="connect-error"><h1>Nadi Connect</h1><p>${esc(e.message)}</p><a href="/">Return to Nadi</a></div>`;});
